-- 404: Original BrillaPrep WASSCE Core Mathematics sprint 1 beta questions, part 2 of 8 (batch wassce-core-math-sprint1-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_404_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_404_guard;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_007' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Given that x + y = 10 and x − y = 2, find the value of x.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 4","B. x = 8","C. x = 6","D. x = 5"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Add the two equations to eliminate y: 2x = 12, so x = 6. Then y = 10 − 6 = 4, and indeed 6 − 4 = 2. Therefore the correct answer is C: x = 6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_007' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_008' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Simplify (2x²y)³ ÷ (4xy²).' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 2x⁶y","B. 4x⁵y","C. 2x⁵y²","D. 2x⁵y"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Cube the bracket first: (2x²y)³ = 8x⁶y³. Dividing by 4xy²: 8 ÷ 4 = 2, x⁶ ÷ x = x⁵ and y³ ÷ y² = y, giving 2x⁵y. Therefore the correct answer is D: 2x⁵y.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Simplify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_008' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_009' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Factorise x² + 5x + 6.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. (x + 2)(x + 3)","B. (x + 1)(x + 6)","C. (x − 2)(x − 3)","D. (x + 5)(x + 1)"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Find two numbers that multiply to 6 and add to 5: they are 2 and 3. Hence x² + 5x + 6 = (x + 2)(x + 3). Therefore the correct answer is A: (x + 2)(x + 3).' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Factorise' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_009' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_010' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the roots of the equation (x − 3)(x + 2) = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = −3 or x = 2","B. x = 3 or x = −2","C. x = 3 or x = 2","D. x = −3 or x = −2"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A product is zero only when a factor is zero: x − 3 = 0 gives x = 3, and x + 2 = 0 gives x = −2. Therefore the correct answer is B: x = 3 or x = −2.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_010' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_011' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'For the function y = x² − 4, find the value of y when x = 3.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 9","B. 1","C. 5","D. 13"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Substitute x = 3 into the function: y = 3² − 4 = 9 − 4 = 5. (The trap answer 9 forgets to subtract 4.) Therefore the correct answer is C: 5.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_011' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_404_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_012' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the discriminant of the quadratic equation x² + 4x + 4 = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 16","B. 8","C. 32","D. 0"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The discriminant is b² − 4ac with a = 1, b = 4 and c = 4: 4² − 4(1)(4) = 16 − 16 = 0, so the equation has one repeated root. Therefore the correct answer is D: 0.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_012' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
